import jax
import jax.numpy as jnp

_BM = 128
_BN = 256
_AQ = 128
_AK = 128


def _mm(x, w):
    m, k = x.shape
    n = w.shape[1]

    def kernel(x_ref, w_ref, acc_ref, out_ref):
        kk = pl.program_id(2)

        @pl.when(kk == 0)
        def init():
            acc_ref[...] = jnp.zeros_like(acc_ref)

        acc_ref[...] += jnp.dot(
            x_ref[...], w_ref[...], preferred_element_type=jnp.float32
        )

        @pl.when(kk == pl.num_programs(2) - 1)
        def store():
            out_ref[...] = acc_ref[...].astype(out_ref.dtype)

    grid = (m // _BM, n // _BN, k // _BN)
    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
        grid_spec=pltpu.GridSpec(
            grid=grid,
            in_specs=[
                pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, kk)),
                pl.BlockSpec((_BN, _BN), lambda i, j, kk: (kk, j)),
            ],
            out_specs=pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((_BM, _BN), jnp.float32)],
        ),
    )(x, w)


def _project(x, w, b, column):
    m, k = x.shape
    n = b.shape[0]
    column_block = column * (n // _BN)

    def kernel(x_ref, w_ref, b_ref, acc_ref, out_ref):
        kk = pl.program_id(2)

        @pl.when(kk == 0)
        def init():
            acc_ref[...] = jnp.zeros_like(acc_ref)

        acc_ref[...] += jnp.dot(
            x_ref[...], w_ref[...], preferred_element_type=jnp.float32
        )

        @pl.when(kk == pl.num_programs(2) - 1)
        def store():
            value = acc_ref[...].astype(out_ref.dtype) + b_ref[...]
            if column == 0:
                scale = 1.0 / jnp.sqrt(jnp.asarray(n, dtype=value.dtype))
                value = value * scale
            out_ref[...] = value

    grid = (m // _BM, n // _BN, k // _BN)
    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
        grid_spec=pltpu.GridSpec(
            grid=grid,
            in_specs=[
                pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, kk)),
                pl.BlockSpec(
                    (_BN, _BN), lambda i, j, kk: (kk, column_block + j)
                ),
                pl.BlockSpec((_BN,), lambda i, j, kk: (j,)),
            ],
            out_specs=pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((_BM, _BN), jnp.float32)],
        ),
    )(x, w, b)


def _attention(q, k, v):
    # q, k, v have shape (heads, length, head_dim).
    heads, length, d = q.shape

    def kernel(q_ref, k_ref, v_ref, m_ref, l_ref, acc_ref, out_ref):
        ki = pl.program_id(2)

        @pl.when(ki == 0)
        def init():
            m_ref[...] = jnp.full_like(m_ref, -jnp.inf)
            l_ref[...] = jnp.zeros_like(l_ref)
            acc_ref[...] = jnp.zeros_like(acc_ref)

        q_tile = q_ref[0, :, :]
        k_tile = k_ref[0, :, :]
        v_tile = v_ref[0, :, :]

        scores = jnp.dot(
            q_tile, k_tile.T, preferred_element_type=jnp.float32
        )
        block_max = jnp.max(scores, axis=1, keepdims=True)
        next_m = jnp.maximum(m_ref[...], block_max)
        correction = jnp.exp(m_ref[...] - next_m)
        p = jnp.exp(scores - next_m).astype(v.dtype)
        next_l = correction * l_ref[...] + jnp.sum(
            p.astype(jnp.float32), axis=1, keepdims=True
        )
        acc_ref[...] = correction * acc_ref[...] + jnp.dot(
            p, v_tile, preferred_element_type=jnp.float32
        )
        m_ref[...] = next_m
        l_ref[...] = next_l

        @pl.when(ki == pl.num_programs(2) - 1)
        def store():
            out_ref[0, :, :] = (acc_ref[...] / l_ref[...]).astype(out_ref.dtype)

    grid = (length // _AQ, heads, length // _AK)
    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct(q.shape, q.dtype),
        grid_spec=pltpu.GridSpec(
            grid=grid,
            in_specs=[
                pl.BlockSpec((1, _AQ, d), lambda qi, hi, ki: (hi, qi, 0)),
                pl.BlockSpec((1, _AK, d), lambda qi, hi, ki: (hi, ki, 0)),
                pl.BlockSpec((1, _AK, d), lambda qi, hi, ki: (hi, ki, 0)),
            ],
            out_specs=pl.BlockSpec(
                (1, _AQ, d), lambda qi, hi, ki: (hi, qi, 0)
            ),
            scratch_shapes=[
                pltpu.VMEM((_AQ, 1), jnp.float32),
                pltpu.VMEM((_AQ, 1), jnp.float32),
                pltpu.VMEM((_AQ, d), jnp.float32),
            ],
        ),
    )(q, k, v)


def _addmm(x, w, residual):
    m, k = x.shape
    n = w.shape[1]

    def kernel(x_ref, w_ref, r_ref, acc_ref, out_ref):
        kk = pl.program_id(2)

        @pl.when(kk == 0)
        def init():
            acc_ref[...] = jnp.zeros_like(acc_ref)

        acc_ref[...] += jnp.dot(
            x_ref[...], w_ref[...], preferred_element_type=jnp.float32
        )

        @pl.when(kk == pl.num_programs(2) - 1)
        def store():
            out_ref[...] = (
                acc_ref[...].astype(out_ref.dtype) + r_ref[...]
            )

    grid = (m // _BM, n // _BN, k // _BN)
    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((m, n), x.dtype),
        grid_spec=pltpu.GridSpec(
            grid=grid,
            in_specs=[
                pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, kk)),
                pl.BlockSpec((_BN, _BN), lambda i, j, kk: (kk, j)),
                pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, j)),
            ],
            out_specs=pl.BlockSpec((_BM, _BN), lambda i, j, kk: (i, j)),
            scratch_shapes=[pltpu.VMEM((_BM, _BN), jnp.float32)],
        ),
    )(x, w, residual)


def workload(x, wq, wk, wv, in_w, in_b, out_w, out_b, w1, w2):
    length, channels = x.shape
    heads = 4
    d = channels // heads

    q0 = _mm(x, wq)
    k0 = _mm(x, wk)
    v0 = _mm(x, wv)

    q = _project(q0, in_w, in_b, 0)
    k = _project(k0, in_w, in_b, 1)
    v = _project(v0, in_w, in_b, 2)

    # Transposing makes the last two block dimensions (_AQ/_AK, d),
    # avoiding a padded singleton dimension inside the attention kernel.
    q = q.reshape(length, heads, d).transpose(1, 0, 2)
    k = k.reshape(length, heads, d).transpose(1, 0, 2)
    v = v.reshape(length, heads, d).transpose(1, 0, 2)

    attn = _attention(q, k, v)
    attn = attn.transpose(1, 0, 2).reshape(length, channels)

    hidden = _addmm(attn, out_w, x)
    ff = _mm(hidden, w1)
    return _addmm(ff, w2, hidden)


