def workload(feat_emb, kernel):
    B, F, E = feat_emb.shape
    P = F * (F - 1) // 2

    pairs = [(i, j) for i in range(F) for j in range(i + 1, F)]
    rows = jnp.asarray([i for i, _ in pairs], dtype=jnp.int32)
    cols = jnp.asarray([j for _, j in pairs], dtype=jnp.int32)

    x = feat_emb.astype(jnp.bfloat16).reshape(B, F * E)
    w = kernel.transpose(1, 0, 2).astype(jnp.bfloat16)

    def pair_kernel(row_ref, col_ref, p_ref, q_ref, w_ref, out_ref):
        projected = jax.lax.dot(
            p_ref[...],
            w_ref[0],
            preferred_element_type=jnp.float32,
        )
        out_ref[...] = jnp.sum(
            projected * q_ref[...],
            axis=1,
            dtype=jnp.float32,
        )

    def p_index(b, g, row_ref, col_ref):
        return (0, row_ref[g])

    def q_index(b, g, row_ref, col_ref):
        return (0, col_ref[g])

    def w_index(b, g, row_ref, col_ref):
        return (g, 0, 0)

    def out_index(b, g, row_ref, col_ref):
        return (g,)

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=2,
        grid=(1, P),
        in_specs=[
            pl.BlockSpec((B, E), p_index),
            pl.BlockSpec((B, E), q_index),
            pl.BlockSpec((1, E, E), w_index),
        ],
        out_specs=pl.BlockSpec((B,), out_index),
    )

    out = pl.pallas_call(
        pair_kernel,
        out_shape=jax.ShapeDtypeStruct((P * B,), jnp.float32),
        grid_spec=grid_spec,
    )(rows, cols, x, x, w)

    return out.reshape(P, B).transpose()

