def workload_entry(q, k, v, g, gs, sink):
    B, HQ, T, D = q.shape
    H = k.shape[1]
    G = HQ // H
    bq = 128 if T >= 128 else T
    nqb = T // bq
    BH = B * HQ

    q2 = q.transpose(0, 1, 2, 3).reshape(BH * T, D)
    k2 = k.transpose(0, 1, 2, 3).reshape(B * H * T, D)
    v2 = v.transpose(0, 1, 2, 3).reshape(B * H * T, D)
    g2 = g.transpose(0, 1, 2, 3).reshape(BH * T, D)
    gs2 = gs.transpose(0, 1, 2).reshape(BH * T)

    def prep_kernel(g_ref, k_ref, gs_ref, p_ref, kn_ref, c_ref):
        gf = g_ref[...].astype(jnp.float32)
        p = jnp.cumsum(gf, axis=0) * _RCP_LN2
        p_ref[...] = p
        c_ref[...] = jnp.cumsum(gs_ref[...].astype(jnp.float32), axis=0) * _RCP_LN2
        kk = k_ref[...].astype(jnp.float32)
        for j in range(nqb):
            start = j * bq
            pa = p[start]
            pj = p[start:start + bq]
            e = jnp.clip(pa[None, :] - pj, -80.0, 80.0)
            kj = kk[start:start + bq] * jnp.exp2(e)
            kn_ref[start:start + bq] = kj.astype(jnp.bfloat16)

    p2, kn2, c2 = pl.pallas_call(
        prep_kernel,
        out_shape=(
            jax.ShapeDtypeStruct((BH * T, D), jnp.float32),
            jax.ShapeDtypeStruct((BH * T, D), jnp.bfloat16),
            jax.ShapeDtypeStruct((BH * T,), jnp.float32),
        ),
        grid=(BH,),
        in_specs=(
            pl.BlockSpec((T, D), lambda bh: (bh, 0)),
            pl.BlockSpec((T, D), lambda bh: (bh // G, 0)),
            pl.BlockSpec((T,), lambda bh: (bh,)),
        ),
        out_specs=(
            pl.BlockSpec((T, D), lambda bh: (bh, 0)),
            pl.BlockSpec((T, D), lambda bh: (bh, 0)),
            pl.BlockSpec((T,), lambda bh: (bh,)),
        ),
    )(g2, k2, gs2)

    def attention_kernel(q_ref, p_ref, kn_ref, v_ref, c_ref, sink_ref, o_ref):
        qi = pl.program_id(1)
        qs = qi * bq
        qf = q_ref[...].astype(jnp.float32)
        pq = p_ref[qs:qs + bq]
        cq = c_ref[qs:qs + bq]
        scale = _RCP_LN2 * (D ** -0.5)

        def body(j, carry):
            m, l, acc = carry
            ks = j * bq
            pa = p_ref[ks]
            qe = jnp.clip(pq - pa[None, :], -80.0, 80.0)
            qg = (qf * jnp.exp2(qe)).astype(jnp.bfloat16)
            kj = kn_ref[ks:ks + bq]
            raw = jax.lax.dot_general(
                qg,
                kj,
                dimension_numbers=(((1,), (1,)), ((), ())),
                preferred_element_type=jnp.float32,
            )
            logits = raw * scale + cq[:, None] - c_ref[ks:ks + bq][None, :]
            ipos = qs + jnp.arange(bq, dtype=jnp.int32)
            jpos = ks + jnp.arange(bq, dtype=jnp.int32)
            causal = jpos[None, :] <= ipos[:, None]
            logits = jnp.where(causal, logits, -jnp.inf)

            mb = jnp.max(logits, axis=1)
            mn = jnp.maximum(m, mb)
            alpha = jnp.exp2(m - mn)
            probs = jnp.exp2(logits - mn[:, None])
            lnew = l * alpha + jnp.sum(probs, axis=1)
            pv = jax.lax.dot_general(
                probs.astype(jnp.bfloat16),
                v_ref[ks:ks + bq],
                dimension_numbers=(((1,), (0,)), ((), ())),
                preferred_element_type=jnp.float32,
            )
            accnew = acc * alpha[:, None] + pv
            return mn, lnew, accnew

        m0 = jnp.full((bq,), -jnp.inf, dtype=jnp.float32)
        l0 = jnp.zeros((bq,), dtype=jnp.float32)
        a0 = jnp.zeros((bq, D), dtype=jnp.float32)
        m, l, acc = jax.lax.fori_loop(0, qi + 1, body, (m0, l0, a0))
        sink_l2 = sink_ref[0].astype(jnp.float32) * _RCP_LN2
        den = l + jnp.exp2(sink_l2 - m)
        o_ref[...] = acc / den[:, None]

    o2 = pl.pallas_call(
        attention_kernel,
        out_shape=jax.ShapeDtypeStruct((BH * T, D), jnp.float32),
        grid=(BH, nqb),
        in_specs=(
            pl.BlockSpec((bq, D), lambda bh, qi: (bh * nqb + qi, 0)),
            pl.BlockSpec((T, D), lambda bh, qi: (bh, 0)),
            pl.BlockSpec((T, D), lambda bh, qi: (bh, 0)),
            pl.BlockSpec((T, D), lambda bh, qi: (bh // G, 0)),
            pl.BlockSpec((T,), lambda bh, qi: (bh,)),
            pl.BlockSpec((1,), lambda bh, qi: (bh % HQ,)),
        ),
        out_specs=pl.BlockSpec((bq, D), lambda bh, qi: (bh * nqb + qi, 0)),
    )(q2, p2, kn2, v2, c2, sink)

    return o2.reshape(B, HQ, T, D)

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def workload(x, w, b):
    batch, in_channels, height, width = x.shape
    out_channels, _, kh, kw = w.shape
    out_h = height - kh + 1
    out_w = width - kw + 1

    def standardize_kernel(w_ref, out_ref):
        dtype = w_ref.dtype
        flat = w_ref[0].astype(jnp.float32).reshape((in_channels * kh * kw,))
        mean = (jnp.sum(flat) / flat.size).astype(dtype)
        centered = (flat - mean.astype(jnp.float32)).astype(dtype)
        centered_f32 = centered.astype(jnp.float32)
        var = (jnp.sum(centered_f32 * centered_f32) / flat.size).astype(dtype)
        denom = jnp.sqrt(var.astype(jnp.float32) + 1e-10).astype(dtype)
        normalized = (centered_f32 / denom.astype(jnp.float32)).astype(dtype)
        out_ref[0] = normalized.reshape((in_channels, kh, kw))

    filter_spec = pl.BlockSpec(
        (1, in_channels, kh, kw), lambda o: (o, 0, 0, 0)
    )
    w_std = pl.pallas_call(
        standardize_kernel,
        out_shape=jax.ShapeDtypeStruct(w.shape, w.dtype),
        grid=(out_channels,),
        in_specs=[filter_spec],
        out_specs=filter_spec,
    )(w)

    block_m = 1 << (out_w - 1).bit_length()
    block_o = out_channels
    padded_w = block_m + kw - 1

    def conv_kernel(x_ref, w_ref, b_ref, out_ref):
        acc = jnp.zeros((block_m, block_o), dtype=jnp.float32)
        for r in range(kh):
            for c in range(kw):
                lhs = x_ref[0, r, c:c + block_m, :].reshape(
                    (block_m, in_channels)
                )
                rhs = w_ref[r, c, :, :].reshape((in_channels, block_o))
                acc += jnp.dot(
                    lhs, rhs, preferred_element_type=jnp.float32
                )
        conv = acc.astype(out_ref.dtype)
        out_ref[0, 0, :, :] = (conv + b_ref[:]).astype(out_ref.dtype)

    def x_index(n, h, o):
        return (n, h, 0, 0)

    def w_index(n, h, o):
        return (0, 0, 0, o)

    def b_index(n, h, o):
        return (o,)

    def out_index(n, h, o):
        return (n, h, 0, o)

    x_nhwc = jnp.transpose(x, (0, 2, 3, 1))
    x_nhwc = jnp.pad(
        x_nhwc,
        ((0, 0), (0, 0), (0, padded_w - width), (0, 0)),
    )
    w_hwio = jnp.transpose(w_std, (2, 3, 1, 0))

    y_nhwc = pl.pallas_call(
        conv_kernel,
        out_shape=jax.ShapeDtypeStruct(
            (batch, out_h, out_w, out_channels), x.dtype
        ),
        grid=(batch, out_h, 1),
        in_specs=[
            pl.BlockSpec((1, kh, padded_w, in_channels), x_index),
            pl.BlockSpec((kh, kw, in_channels, block_o), w_index),
            pl.BlockSpec((block_o,), b_index),
        ],
        out_specs=pl.BlockSpec((1, 1, block_m, block_o), out_index),
    )(x_nhwc, w_hwio, b)

    return jnp.transpose(y_nhwc, (0, 3, 1, 2))

