def _projection_gelu_kernel(x_ref, w_ref, out_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _initialize():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[0, :, :],
        w_ref[0, :, :],
        preferred_element_type=jnp.float32,
    )

    @pl.when(k == pl.num_programs(3) - 1)
    def _finish():
        out_ref[0, :, :] = jax.nn.gelu(
            acc_ref[...], approximate=True
        ).astype(out_ref.dtype)


def _projection_kernel(h_ref, w_ref, out_ref, acc_ref):
    k = pl.program_id(3)

    @pl.when(k == 0)
    def _initialize():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        h_ref[0, :, :],
        w_ref[0, :, :],
        preferred_element_type=jnp.float32,
    )

    @pl.when(k == pl.num_programs(3) - 1)
    def _finish():
        out_ref[0, :, :] = acc_ref[...].astype(out_ref.dtype)


def _first_projection(x, w1):
    experts, capacity, d_model = x.shape
    d_ff = w1.shape[2]
    block_m = 512
    block_n = 512
    block_k = 512

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(
            experts,
            capacity // block_m,
            d_ff // block_n,
            d_model // block_k,
        ),
        in_specs=[
            pl.BlockSpec(
                (1, block_m, block_k),
                lambda e, m, n, k: (e, m, k),
            ),
            pl.BlockSpec(
                (1, block_k, block_n),
                lambda e, m, n, k: (e, k, n),
            ),
        ],
        out_specs=pl.BlockSpec(
            (1, block_m, block_n),
            lambda e, m, n, k: (e, m, n),
        ),
        scratch_shapes=[
            pltpu.VMEM((block_m, block_n), dtype=jnp.float32)
        ],
    )
    return pl.pallas_call(
        _projection_gelu_kernel,
        grid_spec=grid_spec,
        out_shape=jax.ShapeDtypeStruct(
            (experts, capacity, d_ff), x.dtype
        ),
    )(x, w1)


def _second_projection(h, w2):
    experts, capacity, d_ff = h.shape
    d_model = w2.shape[2]
    block_m = 512
    block_n = 512
    block_k = 512

    grid_spec = pltpu.PrefetchScalarGridSpec(
        num_scalar_prefetch=0,
        grid=(
            experts,
            capacity // block_m,
            d_model // block_n,
            d_ff // block_k,
        ),
        in_specs=[
            pl.BlockSpec(
                (1, block_m, block_k),
