def _pool_kernel(x_ref, out_ref, acc_ref):
    step = pl.program_id(2)

    @pl.when(step == 0)
    def _init():
        acc_ref[...] = jnp.full_like(acc_ref, -jnp.inf)

    block_max = jnp.max(x_ref[...], axis=1)
    acc_ref[...] = jnp.maximum(acc_ref[...], block_max)

    @pl.when(step == pl.num_programs(2) - 1)
    def _store():
        out_ref[...] = acc_ref[...].astype(out_ref.dtype)


def _linear1_kernel(x_ref, w_ref, bias_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k == pl.num_programs(2) - 1)
    def _store():
        value = acc_ref[...] + bias_ref[...][None, :]
        value = jnp.where(value >= 0.0, value, 0.01 * value)
        out_ref[...] = value.astype(out_ref.dtype)


def _linear2_kernel(x_ref, w_ref, bias_ref, out_ref, acc_ref):
    k = pl.program_id(2)

    @pl.when(k == 0)
    def _init():
        acc_ref[...] = jnp.zeros_like(acc_ref)

    acc_ref[...] += jnp.dot(
        x_ref[...], w_ref[...], preferred_element_type=jnp.float32
    )

    @pl.when(k == pl.num_programs(2) - 1)
    def _store():
        value = acc_ref[...] + bias_ref[...][None, :]
        out_ref[...] = value.astype(out_ref.dtype)


def workload(x, w1, b1, w2, b2):
    batch, seq_len, features = x.shape
    hidden = w1.shape[1]
    outputs = w2.shape[1]

    pool_bm = 8
    pool_bn = 256
    pool_bl = 128
    mm_bn = 512
    mm_bk = 256

    pooled = pl.pallas_call(
        _pool_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, features), jnp.bfloat16),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(batch // pool_bm, features // pool_bn, seq_len // pool_bl),
            in_specs=[
                pl.BlockSpec(
                    (pool_bm, pool_bl, pool_bn),
                    lambda m, n, step: (m, step, n),
                )
            ],
            out_specs=pl.BlockSpec(
                (pool_bm, pool_bn), lambda m, n, step: (m, n)
            ),
            scratch_shapes=[
                pltpu.VMEM((pool_bm, pool_bn), jnp.float32)
            ],
        ),
    )(x)

    hidden_value = pl.pallas_call(
        _linear1_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, hidden), jnp.bfloat16),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(1, hidden // mm_bn, features // mm_bk),
            in_specs=[
                pl.BlockSpec(
                    (batch, mm_bk), lambda m, n, k: (m, k)
                ),
                pl.BlockSpec(
                    (mm_bk, mm_bn), lambda m, n, k: (k, n)
                ),
                pl.BlockSpec((mm_bn,), lambda m, n, k: (n,)),
            ],
            out_specs=pl.BlockSpec(
                (batch, mm_bn), lambda m, n, k: (m, n)
            ),
            scratch_shapes=[
                pltpu.VMEM((batch, mm_bn), jnp.float32)
            ],
        ),
    )(pooled, w1.astype(jnp.bfloat16), b1)

    return pl.pallas_call(
        _linear2_kernel,
        out_shape=jax.ShapeDtypeStruct((batch, outputs), x.dtype),
        grid_spec=pltpu.PrefetchScalarGridSpec(
            num_scalar_prefetch=0,
            grid=(1, outputs // mm_bn, hidden // mm_bk),
            in_specs=[
                pl.BlockSpec(
                    (batch, mm_bk), lambda m, n, k: (m, k)
                ),
                pl.BlockSpec(
                    (mm_bk, mm_bn), lambda m, n, k: (k, n)
                ),
                pl.BlockSpec((mm_bn,), lambda m, n, k: (n,)),
            ],
            out_specs=pl.BlockSpec(
                (batch, mm_bn), lambda m, n, k: (m, n)
            ),
            scratch_shapes=[
                pltpu.VMEM((batch, mm_bn), jnp.float32)
            ],
        ),
    )(hidden_value, w2.astype(jnp.bfloat16), b2)

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def _relative_mse_kernel(im_ref, ref_ref, out_ref):
    pid = pl.program_id(0)

    im = im_ref[...].astype(jnp.float32)
    ref = ref_ref[...].astype(jnp.float32)
    delta = im - ref
    loss = (delta * delta) / (ref * ref + 0.01)
    block_sum = jnp.sum(
        jnp.reshape(loss, (-1,)), dtype=jnp.float32, keepdims=True
    )

    @pl.when(pid == 0)
    def _initialize():
        out_ref[...] = jnp.zeros_like(out_ref)

    out_ref[...] = out_ref[...] + block_sum

    @pl.when(pid == pl.num_programs(0) - 1)
    def _normalize():
        elements = pl.num_programs(0)
        for size in im_ref.shape:
            elements = elements * size
        out_ref[...] = out_ref[...] * (0.5 / elements)


def workload(im, ref):
    batch, channels, height, width = im.shape
    block_shape = (1, 1, height, width)

    def input_map(pid):
        return (pid // channels, pid % channels, 0, 0)

    result = pl.pallas_call(
        _relative_mse_kernel,
        grid=(batch * channels,),
        in_specs=[
            pl.BlockSpec(block_shape, input_map),
            pl.BlockSpec(block_shape, input_map),
        ],
        out_specs=pl.BlockSpec((1,), lambda pid: (0,)),
        out_shape=jax.ShapeDtypeStruct((1,), jnp.float32),
    )(im, ref)
    return result.reshape(())

