def _sequence_bias_kernel(x_ref, bias_ref, out_ref):
    seq_index = pl.program_id(0)
    last_index = pl.num_programs(0) - 1

    @pl.when(seq_index == last_index)
    def _write_bias():
        out_ref[...] = bias_ref[...] + jnp.zeros_like(out_ref)

    @pl.when(seq_index < last_index)
    def _write_x():
        out_ref[...] = x_ref[...]


