from jax.experimental import pallas as pl


def _vertical_pool(a, k, bh):
    v = a[:, :, :bh, :]
    for j in range(1, k):
        v = jnp.maximum(v, a[:, :, j:j + bh, :])
    return v


def _spp_kernel(x_ref, o_ref):
    x = x_ref[...]
    bh = o_ref.shape[-2]
    bw = o_ref.shape[-1]
    rows = bh + 16

    o_ref[0, 0] = x[0, :, 8:8 + bh, 8:8 + bw]

    # Horizontal five-pixel maxima for every row needed by any level.
    h5 = x[:, :, :rows, 6:6 + bw]
    for off in (-1, 0, 1, 2):
        h5 = jnp.maximum(
            h5, x[:, :, :rows, 8 + off:8 + off + bw]
        )
    o_ref[0, 1] = _vertical_pool(
        h5[:, :, 6:6 + bh + 4, :], 5, bh
    )[0]

    # Each successive level adds two columns on either side.
    h9 = h5
    for off in (-4, -3, 3, 4):
        h9 = jnp.maximum(
            h9, x[:, :, :rows, 8 + off:8 + off + bw]
        )
    o_ref[0, 2] = _vertical_pool(
        h9[:, :, 4:4 + bh + 8, :], 9, bh
    )[0]

    h13 = h9
    for off in (-6, -5, 5, 6):
        h13 = jnp.maximum(
            h13, x[:, :, :rows, 8 + off:8 + off + bw]
        )
    o_ref[0, 3] = _vertical_pool(
        h13[:, :, 2:2 + bh + 12, :], 13, bh
    )[0]

    h17 = h13
    for off in (-8, -7, 7, 8):
        h17 = jnp.maximum(
            h17, x[:, :, :rows, 8 + off:8 + off + bw]
        )
    o_ref[0, 4] = _vertical_pool(h17, 17, bh)[0]


def workload(x):
    n, c, h, w = x.shape

    bc = min(16, c)
    while c % bc:
        bc -= 1
    bh = min(64, h)
    while h % bh:
        bh -= 1

    xp = jnp.pad(
        x,
        ((0, 0), (0, 0), (8, 8), (8, 8)),
        constant_values=-jnp.inf,
    )

    y = pl.pallas_call(
        _spp_kernel,
        grid=(n, c // bc, h // bh),
        in_specs=[
            pl.BlockSpec(
                (1, bc, bh + 16, w + 16),
                lambda ni, ci, hi: (ni, ci, hi, 0),
            )
        ],
        out_specs=pl.BlockSpec(
            (1, 5, bc, bh, w),
            lambda ni, ci, hi: (ni, 0, ci, hi, 0),
