        out_shape=jax.ShapeDtypeStruct((n, 5, c, h, w), x.dtype),
    )(xp)

    return y.reshape(n, 5 * c, h, w)

import jax
import jax.numpy as jnp
from jax.experimental import pallas as pl


def workload(x):
    n, c, h, w = x.shape
    c_left = (c + 1) // 2
    c_right = c - c_left

    # Use channel tiles that never straddle a zero/pooled boundary.
    bc = 16
    while c_left % bc != 0 or c % bc != 0 or c_right % bc != 0:
        bc //= 2

    left_blocks = c_left // bc
    pooled_blocks = c // bc
    out_blocks = left_blocks + pooled_blocks + c_right // bc

    # Keeping both spatial dimensions whole makes the halo blocks legal:
    # their trailing dimensions exactly match those of the padded array.
    xp = jnp.pad(x, ((0, 0), (0, 0), (1, 1), (1, 1)))

    def input_map(ni, oi):
        pooled_oi = jnp.clip(oi - left_blocks, 0, pooled_blocks - 1)
        return (ni, pooled_oi, 0, 0)

    def output_map(ni, oi):
        return (ni, oi, 0, 0)

    def kernel(x_ref, y_ref):
        oi = pl.program_id(1)
        y_ref[0] = jnp.zeros((bc, h, w), dtype=y_ref.dtype)

        is_pooled = (oi >= left_blocks) & (oi < left_blocks + pooled_blocks)

        @pl.when(is_pooled)
        def compute_pool():
            v = x_ref[0].astype(jnp.float32)
            acc = jnp.zeros((bc, h, w), dtype=jnp.float32)
            for di in range(3):
                for dj in range(3):
                    acc += v[:, di:di + h, dj:dj + w]
            y_ref[0] = (acc * (1.0 / 9.0)).astype(y_ref.dtype)

    return pl.pallas_call(
        kernel,
        out_shape=jax.ShapeDtypeStruct((n, 2 * c, h, w), x.dtype),
        in_specs=[
            pl.BlockSpec((1, bc, h + 2, w + 2), input_map),
        ],
        out_specs=pl.BlockSpec((1, bc, h, w), output_map),
        grid=(n, out_blocks),
    )(xp)
